// Protege TODO o site (index.html, painel_publico.html e qualquer outro arquivo do
// mesmo repositorio) com uma tela de login estilizada, com a marca do Grupo Bandeira
// Mobilidade (GBM -- rebrand em 2026-08-16, login deixou de ser so da Viacao Sete e
// passou a representar o grupo inteiro), em vez do popup nativo e feio do navegador.
// A verificacao continua acontecendo aqui no servidor do Vercel, ANTES de qualquer
// conteudo real ser enviado.
//
// Como funciona:
// 1. Se o visitante nao tiver um cookie de sessao valido, ve a pagina de login abaixo.
// 2. Ao enviar o formulario (POST para /__login), o usuario/senha sao conferidos
//    contra a lista em SITE_USERS (Environment Variable do Vercel, formato
//    "usuario1:senha1|usuario2:senha2").
// 3. Se bater, grava um cookie assinado (HMAC-SHA256, usando o segredo AUTH_SECRET) e
//    redireciona para a pagina real. O cookie dura 12 horas.
// 4. Nada disso fica escrito aqui no codigo alem da logica -- usuario/senha ficam so
//    nas Environment Variables, entao este arquivo pode ficar num repositorio publico.
//
// Environment Variables necessarias no Vercel (Settings > Environment Variables):
//   SITE_USERS  = usuario1:senha1|usuario2:senha2|usuario3:senha3
//   AUTH_SECRET = qualquer texto longo e aleatorio (usado so para assinar o cookie)
import { next } from '@vercel/functions';

export const config = {
  matcher: '/:path*',
};

const LOGO_BASE64 = '';

const COOKIE_NAME = 'vs_auth';
const SESSION_HOURS = 12;

function credenciaisValidas() {
  const raw = process.env.SITE_USERS || '';
  return raw
    .split('|')
    .map((par) => par.trim())
    .filter(Boolean)
    .map((par) => {
      const i = par.indexOf(':');
      if (i === -1) return null;
      return [par.slice(0, i), par.slice(i + 1)];
    })
    .filter(Boolean);
}

async function assinar(usuario) {
  const secret = process.env.AUTH_SECRET || 'defina-AUTH_SECRET-no-vercel';
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(usuario));
  const hex = [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, '0')).join('');
  return usuario + '.' + hex;
}

async function cookieValido(valor) {
  if (!valor) return false;
  const idx = valor.lastIndexOf('.');
  if (idx === -1) return false;
  const usuario = valor.slice(0, idx);
  const esperado = await assinar(usuario);
  return esperado === valor;
}

function paginaLogin(erro) {
  return `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Grupo Bandeira Mobilidade - Painel de Indicadores</title>
<style>
  :root{--azul:#00579c;--azul-dark:#00304f;--dourado:#efae25;--dourado-dark:#c98f11;}
  *{box-sizing:border-box;}
  body{
    margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;
    font-family:-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
    background:
      radial-gradient(ellipse 900px 500px at 50% -10%, rgba(239,174,37,.16) 0%, rgba(239,174,37,0) 60%),
      linear-gradient(160deg, #013f6b 0%, #00304f 55%, #001b2e 100%);
    padding:24px;
  }
  .card{
    width:100%;max-width:380px;background:#fff;border-radius:18px;
    box-shadow:0 20px 60px rgba(0,0,0,.35);overflow:hidden;
    animation:subir .4s ease;
  }
  @keyframes subir{from{opacity:0;transform:translateY(12px);}to{opacity:1;transform:translateY(0);}}
  .card-top{background:#fff;border:2px solid var(--azul);border-radius:14px;margin:18px 18px 0;padding:26px 24px;text-align:center;}
  .card-top img{max-width:190px;display:block;margin:0 auto;}
  .card-body{padding:26px 28px 30px;}
  label{display:block;font-size:12px;color:#5b6472;font-weight:600;margin:0 0 6px;}
  input{
    width:100%;padding:11px 13px;margin:0 0 16px;border:1.5px solid #dde1ea;border-radius:9px;
    font-size:14px;color:var(--azul-dark);background:#f7f8fb;transition:border-color .15s,background .15s;
  }
  input:focus{outline:none;border-color:var(--azul);background:#fff;}
  button{
    width:100%;padding:12px;border:2px solid var(--azul);border-radius:9px;background:#fff;color:var(--azul);
    font-size:14px;font-weight:700;letter-spacing:.3px;cursor:pointer;transition:background .15s,color .15s;
  }
  button:hover{background:var(--azul);color:#fff;}
  .erro{
    background:#fdecec;color:#8f1226;border:1px solid #f6c9cc;border-radius:8px;
    font-size:12.5px;padding:9px 12px;margin:0 0 16px;text-align:center;
  }
  .rodape{text-align:center;font-size:11px;color:#9aa1ad;margin-top:18px;}
</style>
</head>
<body>
  <div class="card">
    <div class="card-top">
      <img src="data:image/png;base64,${LOGO_BASE64}" alt="Grupo Bandeira Mobilidade">
    </div>
    <div class="card-body">
      <form method="POST" action="/__login">
        ${erro ? '<div class="erro">Usuario ou senha incorretos.</div>' : ''}
        <label for="usuario">Usuario</label>
        <input id="usuario" name="usuario" type="text" autocomplete="username" autofocus required>
        <label for="senha">Senha</label>
        <input id="senha" name="senha" type="password" autocomplete="current-password" required>
        <button type="submit">Entrar</button>
      </form>
      <div class="rodape">Acesso restrito - Grupo Bandeira Mobilidade</div>
    </div>
  </div>
</body>
</html>`;
}

export default async function middleware(request) {
  const url = new URL(request.url);

  // /api/dados fica FORA do login -- e a rota de sincronizacao automatica ("Opcao 3")
  // entre os 4 paineis locais (admin) e os 4 publicos, adicionada em 2026-08-15. Ela
  // precisa responder sem cookie de sessao porque: (1) o painel Comercial local
  // ("Painel Viacao Sete.html") roda fora deste dominio, aberto via file://, entao
  // nunca teria o cookie HttpOnly deste site pra mandar junto; e (2) essa rota ja tem
  // sua propria protecao (POST exige "Authorization: Bearer <SYNC_TOKEN>", GET e
  // leitura publica de proposito -- e o mesmo dado que ja fica visivel pra quem loga
  // e abre qualquer _publico.html). Sem este bypass, o middleware intercepta a
  // chamada antes de chegar em api/dados.js e devolve a pagina de login (HTML) no
  // lugar do JSON esperado, quebrando a sincronizacao silenciosamente.
  if (url.pathname === '/api/dados') {
    return next();
  }

  if (request.method === 'POST' && url.pathname === '/__login') {
    let usuario = '', senha = '';
    try {
      const form = await request.formData();
      usuario = String(form.get('usuario') || '');
      senha = String(form.get('senha') || '');
    } catch (e) {
      // corpo mal formado -- cai para login invalido abaixo
    }
    const validos = credenciaisValidas();
    const ok = validos.some(([u, p]) => u === usuario && p === senha);
    if (ok) {
      const token = await assinar(usuario);
      const headers = new Headers();
      headers.set('Location', '/');
      headers.set('cache-control', 'no-store, must-revalidate');
      headers.append(
        'Set-Cookie',
        `${COOKIE_NAME}=${encodeURIComponent(token)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${SESSION_HOURS * 3600}`
      );
      return new Response(null, { status: 303, headers });
    }
    return new Response(paginaLogin(true), {
      status: 401,
      headers: {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'no-store, must-revalidate',
      },
    });
  }

  // Botao "Sair" do painel (so aparece no modo publico, ver header#headerPublico em
  // painel.html): navegacao simples pra essa rota, sem precisar de JS pra manipular
  // cookie (o cookie e HttpOnly de proposito, entao o navegador nao deixaria o JS da
  // pagina apagar ele mesmo). Aqui no servidor apagamos o cookie (Max-Age=0) e manda
  // de volta pra "/", que cai direto na tela de login de novo.
  if (url.pathname === '/__logout') {
    const headers = new Headers();
    headers.set('Location', '/');
    headers.set('cache-control', 'no-store, must-revalidate');
    headers.append(
      'Set-Cookie',
      `${COOKIE_NAME}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`
    );
    return new Response(null, { status: 303, headers });
  }

  const cookieHeader = request.headers.get('cookie') || '';
  const match = cookieHeader.match(new RegExp(COOKIE_NAME + '=([^;]+)'));
  const valorCookie = match ? decodeURIComponent(match[1]) : null;

  if (await cookieValido(valorCookie)) {
    return next();
  }

  return new Response(paginaLogin(false), {
    status: 200,
    headers: {
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store, must-revalidate',
    },
  });
}
